diff --git a/src/mcos.c b/src/mcos.c
index a3e26c5..3b33a32 100644
--- a/src/mcos.c
+++ b/src/mcos.c
@@ -82,15 +82,22 @@ ParseOpaqueMetadata(const mat_uint32_t *meta, size_t meta_nvals, matvar_t *matva
     }

     obj_start = dim_start + ndims;
-    if ( total_objs > 0 && (size_t)obj_start + total_objs < meta_nvals ) {
-        matvar->internal->num_objects = total_objs;
-        matvar->internal->object_ids = (mat_uint32_t *)malloc(total_objs * sizeof(mat_uint32_t));
+    if ( total_objs > 0 && (size_t)obj_start < meta_nvals ) {
+        size_t num_objs = total_objs;
+
+        /* The id list may be shorter than the dimensions indicate; read as many
+         * object ids as are stored and take the class id after them. */
+        if ( num_objs > meta_nvals - obj_start - 1 )
+            num_objs = meta_nvals - obj_start - 1;
+
+        matvar->internal->num_objects = num_objs;
+        matvar->internal->object_ids = (mat_uint32_t *)malloc(num_objs * sizeof(mat_uint32_t));
         if ( matvar->internal->object_ids != NULL ) {
             size_t k;
-            for ( k = 0; k < total_objs; k++ )
+            for ( k = 0; k < num_objs; k++ )
                 matvar->internal->object_ids[k] = meta[obj_start + k];
         }
-        matvar->internal->class_id = meta[obj_start + total_objs];
+        matvar->internal->class_id = meta[obj_start + num_objs];
     }

     return MATIO_E_NO_ERROR;

